def _platform_excludes() -> list[str]:
    system = platform.system()
    if system == "Darwin":
        return _MACOS_EXCLUDES
    elif system == "Linux":
        return _LINUX_EXCLUDES
    elif system == "Windows":
        return _WINDOWS_EXCLUDES
    return []


DEFAULT_EXCLUDE_GLOBS = _COMMON_EXCLUDES + _platform_excludes()

DEFAULT_SHELL_HISTORY_FILES = [
    ".zsh_history",
    ".bash_history",
    ".python_history",
    ".psql_history",
    ".mysql_history",
    ".node_repl_history",
    ".local/share/fish/fish_history",
    ".lesshst",
]

DEFAULT_MAX_FILE_SIZE = 10 * 1024 * 1024  # 10MB


@dataclass
class Config:
    paths: list[str] = field(default_factory=lambda: [str(Path.home())])
    modules: list[Module] = field(default_factory=lambda: list(Module))
    exclude_globs: list[str] = field(default_factory=list)
    no_default_excludes: bool = False
    include_volumes: bool = False
    max_file_size: int = DEFAULT_MAX_FILE_SIZE
    min_severity: Severity = Severity.LOW
    min_confidence: Confidence = Confidence.LOW
    rules_file: str = ""
    concurrency: int = 0
    reveal_length: bool = False
    output_dir: str = ""
    formats: list[str] = field(default_factory=lambda: ["table"])

    def effective_excludes(self) -> list[str]:
        if self.no_default_excludes:
            return list(self.exclude_globs)
        return DEFAULT_EXCLUDE_GLOBS + list(self.exclude_globs)

    @staticmethod
    def default() -> Config:
        from secretscan.model import DEFAULT_MODULES
        return Config(
            paths=[str(Path.home())],
            modules=list(DEFAULT_MODULES),
        )
